mapper.select:
SELECT COUNT(*)
FROM employee
WHERE shop_id = #{shopId}

    AND real_name LIKE CONCAT('%', #{realName}, '%')


    AND enabled = #{enabled}

SELECT e.id, e.username, e.password, e.real_name, e.phone, e.shop_id, e.role_id, e.enabled, e.create_time, e.update_time, r.role_code AS role_code FROM employee e INNER JOIN role r ON e.role_id = r.id WHERE e.shop_id = #{shopId}
AND e.real_name LIKE CONCAT('%', #{realName}, '%')
AND e.enabled = #{enabled}
ORDER BY e.id DESC LIMIT #{pageSize} OFFSET #{offset}
